--- a/src/worker.ts
+++ b/src/worker.ts
@@ -118,6 +118,10 @@ export class Worker extends EventEmitter {
     const job = await this.store.next(this.keys.wait, this.opts.pollMs);
-    if (!job) return;
+    if (!job) {
+      if (this.active.size === 0) this.emit('drained');
+      return;
